// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para numero
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Pega o primeiro (e único) item da entrada que contém todas as listas
const inputData = $input.all()[0].json;

// Extrai as listas de clientes e investimentos
const clientes = inputData.body.clientes || [];
const investimentos = inputData.investimentos || [];

const resultadoFinal = [];

for (let i = 0; i < clientes.length; i++) {
    const cliente = clientes[i];
    const nome = cliente.nome || "Cliente";
    const email = cliente.email;
    const perfil = cliente.perfil;
    const saldoTexto = cliente.saldo || "R$ 0,00";

    // Converte saldo "R$ 12.500,00" para o número matemático 12500.00
    const saldoNumerico = Number(saldoTexto.replace(/[^\d,]/g, "").replace(",", "."));

    // Filtra os investimentos que batem com o perfil do cliente E que cabem no saldo
    const produtosValidos = investimentos.filter(inv => {
        return inv.perfil === perfil && saldoNumerico >= inv.minimo;
    });

    // Monta a mensagem
    let mensagem = "Olá, " + nome + "!\n\n";
    mensagem += "Analisamos o seu perfil investidor (" + perfil + ") e o seu saldo atual de " + saldoTexto + ".\n";

    if (produtosValidos.length > 0) {
        mensagem += "Baseado nisso, separamos as seguintes oportunidades ideais para você:\n\n";

        for (let j = 0; j < produtosValidos.length; j++) {
            const prod = produtosValidos[j];
            mensagem += "🔹 " + prod.produto + "\n";
            mensagem += "   Rentabilidade: " + prod.rentabilidade + "\n";
            mensagem += "   Aplicação Mínima: R$ " + prod.minimo + ",00\n\n";
        }

        mensagem += "Qual destas opções faz mais sentido para seus objetivos hoje?";
    } else {
        mensagem += "No momento, os produtos do seu perfil exigem um aporte inicial maior do que o seu saldo atual. Continue poupando, logo teremos ótimas opções!\n";
    }

    // Adiciona o cliente processado à lista de saída
    resultadoFinal.push({
        json: {
            nome: nome,
            email: email,
            perfil: perfil,
            mensagem_recomendacao: mensagem
        }
    });
}

return resultadoFinal;

const items = $input.all();

// Mantendo a função parseBRL
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente
const out = items.map(item => {
  const c = item.json;

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,

      mensagem_base: c.mensagem_recomendacao || "",

      // Regras de formatação
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

