const items = $input.all();
const resultados = [];

const nomeDoNoAnterior = "normalizar para IA"; 

for (let i = 0; i < items.length; i++) {
    const item = items[i].json;

    // 1. Extrair o texto bruto devolvido pela IA
    const textoIA = item.content.parts[0].text;

    // 2. Limpar a marcação Markdown (```json e ```) para sobrar apenas o objeto
    const jsonLimpo = textoIA.replace(/```json/gi, "").replace(/```/gi, "").trim();

    // 3. Transformar o texto em um objeto JSON utilizável
    let dadosEmail = {};
    try {
        dadosEmail = JSON.parse(jsonLimpo);
    } catch (erro) {
        // Fallback de segurança caso a IA não retorne um JSON perfeito
        dadosEmail = {
            subject: "Sua recomendação de investimentos",
            text_body: jsonLimpo,
            html_body: "<p>" + jsonLimpo + "</p>"
        };
    }

    // 4. Resgatar as variáveis de envio usando o índice [i] da execução
    let emailDestino = "";
    let nomeCliente = "";
    try {
        const itemOriginal = $items(nomeDoNoAnterior)[i].json;
        emailDestino = itemOriginal.email_to;
        nomeCliente = itemOriginal.nome;
    } catch (e) {
        emailDestino = "erro_ao_buscar_email@verifique.o.nome.do.no";
    }

    // 5. Estruturar a saída final padronizada para os nós de envio de e-mail (Gmail/Outlook)
    resultados.push({
        json: {
            email_to: emailDestino,
            nome: nomeCliente,
            subject: dadosEmail.subject,
            text_body: dadosEmail.text_body,
            html_body: dadosEmail.html_body
        }
    });
}

return resultados;

const falhas = $input.all();

if (falhas.length === 0) {
    return [];
}

let listaHTML = "<ul>";
for (let i = 0; i < falhas.length; i++) {
    const cliente = falhas[i].json;
    listaHTML += "<li><b>" + cliente.nome + ":</b> " + cliente.email_to + "</li>";
}
listaHTML += "</ul>";

let mensagemFinal = "<p>Olá!</p>";
mensagemFinal += "<p>A automação encontrou <b>" + falhas.length + "</b> cliente(s) com endereços de e-mail em formato inválido.</p>";
mensagemFinal += "<p>Aqui está a lista para você tentar contato de outra forma:</p>";
mensagemFinal += listaHTML;

const assuntoFinal = "Atenção: " + falhas.length + " e-mails inválidos bloqueados";

return [{
    json: {
        assunto: assuntoFinal,
        corpo_email: mensagemFinal
    }
}];
